            assertEquals("Wrong interpolation in parent", "/home/foo/path" + i, config.getString("test.absolute.dir.dir" + i));
            assertEquals("Wrong interpolation in subnode", "/home/foo/path" + i, sub.getString("dir" + i));
        }
    }

