docstring:
/**
     * Checks if all events has been processed.
     */

method_definition:
public void done() {
        assertTrue("Too many events received", events.isEmpty());
    }

public T nextEvent(final EventType<?> expectedType) {
        assertFalse("Too few events received", events.isEmpty());
        final T e = events.remove(0);
        if (expectedSource != null) {
            assertEquals("Wrong event source", expectedSource, e.getSource());
        }
        assertEquals("Wrong event type", expectedType, e.getEventType());
        return e;
    }

@Override
    public void onEvent(final T event) {
        events.add(event);
    }

public void skipToLast(final EventType<?> type) {
        while (events.size() > 1) {
            final T e = events.remove(0);
            assertNotSame("Found end event in details", type, e.getEventType());
        }
    }

private void checkSubnodeEvent(final ConfigurationEvent event, final boolean before) {
        assertEquals("Wrong before flag of nesting event", before, event.isBeforeUpdate());
        assertTrue("No subnode event found in value", event.getPropertyValue() instanceof ConfigurationEvent);
        final ConfigurationEvent evSub = (ConfigurationEvent) event.getPropertyValue();
        assertEquals("Wrong event type", ConfigurationEvent.ADD_PROPERTY, evSub.getEventType());
        assertEquals("Wrong property name", "newProp", evSub.getPropertyName());
        assertEquals("Wrong property value", "newValue", evSub.getPropertyValue());
        assertEquals("Wrong before flag", before, evSub.isBeforeUpdate());
    }

