            .withPrefixLookups(prefixLookups)
            .withDefaultLookups(Arrays.asList(defLook1, defLook2))
            .create();
        checkPrefixLookups(spec, prefLook1, prefLook2);
        checkDefaultLookups(spec, defLook1, defLook2);
    }

